arguments.new_string:
for bad in 2025-13-01 2025-00-10 2025-01-32 2025-01-00; do
  ARCHIVE=$t bash tools/purge-archive --before "$bad" >/dev/null 2>&1; [ $? = 2 ] || { echo "a bad date $bad should exit 2"; fail=1; }
done
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a bad date range deleted rows"; fail=1; }
u=$(ARCHIVE=$t bash tools/purge-archive 2>&1); [ "$u" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line: $u"; fail=1; }
e=$(mktemp); printf '# h\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$e"
out=$(ARCHIVE=$e bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same date) failed"; fail=1; }
[ "$out" = "purged 0 row(s) before 2025-01-01 from $e" ] || { echo "same-date purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$e")" = 2 ] && grep -q 'z$' "$e" || { echo "purge --before deleted the same-date row"; fail=1; }
rm -f "$e" "$t"; exit $fail

